const $=s=>document.querySelector(s),app=$('#app');
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let records=read('nur-records',{}),fasts=read('nur-fasts',{}),settings=read('nur-settings',{}),city=read('nur-city','Baku'),prayers=null,day=placeToday(),month=new Date(),surahs=[],route='',period=7,bearing=null;
const names=['Sübh','Zöhr','İkindi','Məğrib','İşa'],icons=['☀','☼','☀','◒','☾'],cities={Baku:'Bakı',Ganja:'Gəncə',Sumqayit:'Sumqayıt',Shaki:'Şəki',Lankaran:'Lənkəran',Nakhchivan:'Naxçıvan'};
const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,date=d=>localizedDate(d),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['home','⌂','Ana səhifə'],['quran','▥','Quran'],['tasbih','◉','Təsbeh'],['duas','♧','Dualar'],['more','•••','Daha çox']],extra=[['prayers','☼','Namaz vaxtları'],['qibla','◈','Qiblə'],['fasting','☾','Oruc təqvimi'],['tracker','✓','Namaz izləyicisi'],['stats','▥','Statistika'],['notifications','♧','Bildirişlər']];
extra.push(['pro','✦','Shams Pro'],['language','◎','Dil seçimi'],['learn','♧','Namazı öyrən'],['mobile','▯','Telefona əlavə et'],['themes','◐','Temalar'],['ramadan','☾','Ramazan']);
function go(r){location.hash=r}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function head(t,s="",back=false){return `<div class="pagehead"><div><h1>${tr(t)}</h1>${s?`<p class="muted">${tr(s)}</p>`:""}</div></div>`}
const mosque=`<svg viewBox="0 0 600 300"><defs><radialGradient id="sky"><stop stop-color="#8c9151"/><stop offset="1" stop-color="#073b32"/></radialGradient><linearGradient id="dome"><stop stop-color="#78966a"/><stop offset="1" stop-color="#123c2c"/></linearGradient></defs><path fill="url(#sky)" d="M0 0h600v300H0z"/><circle cx="395" cy="65" r="25" fill="#e3c27b"/><circle cx="405" cy="57" r="24" fill="#375e43"/><g fill="#0b3429" stroke="#b99b60"><path d="M200 300V180h170v120M185 180Q190 145 235 125Q285 103 285 85Q285 103 330 125Q378 145 385 180Z" fill="url(#dome)"/><path d="M285 85V60M282 66h6M162 300V100h15v200M158 100h23l-11-25zM169 75V30M400 300V110h14v190M396 110h23l-11-25zM407 85V40M440 300V225h120v75M430 225Q435 195 473 179Q500 168 500 152Q500 170 525 180Q561 195 570 225Z"/></g><g fill="#ddbb72"><path d="M220 225q8-20 16 0v38h-16M255 225q8-20 16 0v38h-16M290 225q8-20 16 0v38h-16M325 225q8-20 16 0v38h-16M460 254q6-15 12 0v20h-12M490 254q6-15 12 0v20h-12M520 254q6-15 12 0v20h-12"/></g><path fill="#062e22" d="M0 300v-30q50-70 95 0q45-30 90 20q50-20 90 10M350 300q50-40 95-15q50-50 90-10q40-70 65-10v35"/></svg>`;
function citySelect(){return `<select aria-label="Şəhər" onchange="city=this.value;save('nur-city',city);loadTimes()">${Object.entries(cities).map(([k,v])=>`<option value="${k}" ${k===city?'selected':''}>${v}, Azərbaycan</option>`).join('')}</select>`}
let timeError=false;
async function loadTimes(){return loadWorldTimes()}
function note(){return worldNote()}
function next(){return worldNext()}
function home(){const n=next();return head('Bu gün',date(new Date()))+`<section class="hero"><span class="eyebrow">BİSMİLLAHİR-RƏHMANİR-RƏHİM</span><h2>Qəlbinizə nur dolsun.</h2><p>Hər yeni gün, Allaha yaxınlaşmaq üçün<br>gözəl bir başlanğıcdır.</p><button class="goldbtn" onclick="go('quran')">Quran oxumağa başla &nbsp; →</button>${mosque}</section><button class="learn-banner" onclick="go('learn')"><span class="learn-symbol">♧</span><span><strong>Namaz necə qılınır?</strong><small>Hənəfi və Cəfəri · addım-addım təlimat</small></span><span>→</span></button><div class="homegrid"><section class="card next"><div><span class="muted">Növbəti namaz · ${cities[city]}</span><h2>${n?names[n.i]:'Namaz vaxtları'}</h2><div class="time">${n?prayers[n.i]:'— : —'}</div><span class="muted">${n?n.left:timeError?'Bağlantını yoxlayın':'Vaxtlar yüklənir…'}</span></div><span class="bigicon">♧</span></section><div class="quickgrid">${[extra[0],nav[1],nav[2],extra[1]].map(([r,i,t])=>`<button class="quick" onclick="go('${r}')"><span>${i}</span>${t}</button>`).join('')}</div></div><div class="sectiontitle"><h2>Bu günün namaz vaxtları</h2><button class="textbtn" onclick="go('prayers')">Hamısına bax →</button></div><div class="prayerstrip">${names.map((t,i)=>`<div class="prayerbox ${n?.i===i?'current':''}"><span class="sun">${icons[i]}</span>${t}<strong>${prayers?.[i]||'—:—'}</strong></div>`).join('')}</div>${note()}<div class="quote"><span class="ornament">─ ❈ ─</span><p>“Qəlblər yalnız Allahı zikr etməklə rahatlıq tapar.”</p><small>RƏD SURƏSİ, 28</small></div>`}
function shiftDay(n){day.setDate(day.getDate()+n);loadTimes()}
function prayerPage(track=false){const a=records[key(day)]||[];return head(track?'Namaz izləyicisi':'Namaz vaxtları','İbadətinizə hər gün vaxt ayırın')+`<div class="toolbar">${worldCitySelect()}</div><section class="card"><div class="calendarhead"><button class="textbtn" onclick="shiftDay(-1)">❮</button><span>${date(day)}</span><button class="textbtn" onclick="shiftDay(1)">❯</button></div>${names.map((n,i)=>`<div class="row"><span class="symbol">${icons[i]}</span><strong class="grow">${n}</strong><span>${prayers?.[i]||'—:—'}</span>${track?`<input type="checkbox" class="check" aria-label="${n} qılındı" ${a.includes(i)?'checked':''} onchange="togglePrayer(${i})">`:`<input type="checkbox" class="switch" aria-label="${n} bildirişi" ${settings[i]?'checked':''} onchange="setNotice('${i}',this.checked)">`}</div>`).join('')}${track?`<div class="sectiontitle"><strong>Bu günün irəliləyişi</strong><span>${a.length}/5</span></div><div class="progress"><div style="width:${a.length*20}%"></div></div>`:''}${note()}</section>`}
function togglePrayer(i){let a=records[key(day)]||[];records[key(day)]=a.includes(i)?a.filter(n=>n!==i):[...a,i];save('nur-records',records);render()}
async function loadSurahs(){try{surahs=read('nur-surahs',[]);if(!surahs.length){const r=await fetch('https://api.alquran.cloud/v1/surah',{signal:AbortSignal.timeout(12000)}),j=await r.json();surahs=j.data;save('nur-surahs',surahs)}}catch{surahs=[{number:1,englishName:'Fatihə',name:'الفاتحة',numberOfAyahs:7},{number:112,englishName:'İxlas',name:'الإخلاص',numberOfAyahs:4},{number:113,englishName:'Fələq',name:'الفلق',numberOfAyahs:5},{number:114,englishName:'Nas',name:'الناس',numberOfAyahs:6}]}if(route==='quran')render()}
function surahRows(list){return list.length?list.map(s=>`<button class="row" onclick="go('read/${s.number}')"><span class="number">${s.number}</span><div class="grow"><strong>${s.number===1?'Fatihə':esc(s.englishName)}</strong><small>${s.numberOfAyahs} ayə</small></div><span style="font:23px Amiri">${esc(s.name)}</span>›</button>`).join(''):'<p class="muted">Surə tapılmadı.</p>'}
function quran(){return head('Qurani-Kərim','Oxu, dinlə, qəlbinə nur qat')+`<div class="toolbar"><input type="search" aria-label="Surə axtarışı" placeholder="Surə axtarın…" oninput="filterSurahs(this.value)"></div><section class="card listgrid" id="surahList">${surahRows(surahs)}</section><p class="notice">Mətn və Azərbaycan dilində tərcümə: Al Quran Cloud · Oxunuş: Mişari Rəşid əl-Əfasi.</p>`}
function filterSurahs(q){$('#surahList').innerHTML=surahRows(surahs.filter(s=>(s.englishName+s.name+s.number+(s.number===1?'Fatihə':'')).toLocaleLowerCase('az').includes(q.toLocaleLowerCase('az'))))}
async function reader(id){const readingLang=lang();app.innerHTML=head('Oxu','',true)+'<div class="card center">Ayələr yüklənir…</div>';try{let j=read('nur-surah-'+readingLang+'-'+id,null);if(!j){const r=await fetch(`https://api.alquran.cloud/v1/surah/${id}/editions/quran-uthmani,${({az:"az.mammadaliyev",tr:"tr.diyanet",ru:"ru.kuliev",en:"en.sahih",ar:"ar.muyassar"})[readingLang]}`,{signal:AbortSignal.timeout(18000)});j=await r.json();if(j.code!==200)throw Error();save('nur-surah-'+readingLang+'-'+id,j)}if(location.hash!==`#read/${id}`||lang()!==readingLang)return;const [ar,az]=j.data;app.innerHTML=head('Oxu','',true)+`<section class="reading"><h2>${esc(ar.englishName)}</h2><span class="muted">${ar.numberOfAyahs} ayə</span><audio controls preload="none" aria-label="Surəni dinlə" src="https://cdn.islamic.network/quran/audio-surah/128/ar.alafasy/${id}.mp3"></audio><button class="textbtn" onclick="document.querySelectorAll('.arabic').forEach(e=>e.style.fontSize=e.style.fontSize==='40px'?'30px':'40px')">Aa · Yazı ölçüsü</button><div class="ornament">─ ❈ ─</div>${ar.ayahs.map((a,i)=>`<div class="ayah"><div class="arabic" lang="ar">${esc(a.text)} <small style="font-size:16px">﴿${i+1}﴾</small></div><p>${esc(az.ayahs[i].text)}</p></div>`).join('')}</section>`;localizeUI()}catch{if(route==='read')app.innerHTML=head('Oxu','',true)+`<div class="card error">Ayələr yüklənmədi. İnternet bağlantısını yoxlayın.<p><button class="goldbtn" onclick="reader(${id})">Yenidən yoxla</button></p></div>`}}
const duas=[['☀','Səhər duaları','Günə Allahla yaxın başlayın','اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ','Allahummə bikə əsbəhnə və bikə əmsəynə və bikə nəhyə və bikə nəmutu və ileykən-nuşur.','Allahım! Səninlə səhərə çıxdıq, Səninlə axşama yetişdik. Səninlə yaşayır, Səninlə ölürük. Diriliş Sənədir.'],['☾','Axşam duaları','Günü dua ilə tamamlayın','اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ','Allahummə bikə əmsəynə və bikə əsbəhnə və bikə nəhyə və bikə nəmutu və ileykəl-məsir.','Allahım! Səninlə axşama yetişdik, Səninlə səhərə çıxdıq. Səninlə yaşayır, Səninlə ölürük. Dönüş Sənədir.'],['♜','Yemək duaları','Ruziyə şükür edək','بِسْمِ اللَّهِ','Bismilləh.','Allahın adı ilə.'],['♧','Səfər duaları','Yolda təhlükəsizliyiniz üçün','سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ','Subhanəlləzi səxxara lənə həzə və mə kunnə ləhu muqrinin. Və innə ilə Rabbinə ləmunqalibun.','Bunu bizə ram edən pak və müqəddəsdir. Bizim buna gücümüz çatmazdı. Biz Rəbbimizə qayıdacağıq.'],['⌂','Evin duaları','Eviniz üçün bərəkət','بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا','Bismilləhi vələcnə və bismilləhi xaracnə və aləllahi Rabbinə təvəkkəlnə.','Allahın adı ilə daxil olduq, Allahın adı ilə çıxdıq və Rəbbimiz Allaha təvəkkül etdik.'],['♧','Müxtəlif dualar','Həyatın hər anı üçün','رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ','Rabbənə ətinə fid-dunyə həsənətən və fil-axirəti həsənətən və qinə əzabən-nər.','Ey Rəbbimiz! Bizə dünyada da, axirətdə də yaxşılıq ver və bizi od əzabından qoru.']];
function duaPage(id){if(id===undefined)return head('Gündəlik dualar','Həyatın hər anında, dilinizdə dua')+`<section class="card listgrid">${duas.map((d,i)=>`<button class="row" onclick="go('dua/${i}')"><span class="symbol">${d[0]}</span><div class="grow"><strong>${d[1]}</strong><small>${d[2]}</small></div>›</button>`).join('')}</section>`;const d=duas[id];if(!d)return duaPage();return head(d[1],'',true)+`<section class="hero" style="min-height:180px">${mosque}<h2>${d[2]}</h2></section><section class="reading" style="margin-top:24px"><div class="arabic" lang="ar">${d[3]}</div><div class="ornament">─ ❈ ─</div><p>${d[4]}</p><div class="meaning"><strong>Mənası:</strong><br>${d[5]}</div></section>`}
function fasting(){const y=month.getFullYear(),m=month.getMonth(),o=(new Date(y,m,1).getDay()+6)%7,n=new Date(y,m+1,0).getDate();return head('Oruc təqvimi','Oruc tutduğunuz günləri qeyd edin')+`<div class="split"><section class="card"><div class="calendarhead"><button class="textbtn" onclick="shiftMonth(-1)">❮</button><h2>${month.toLocaleDateString('az-AZ',{month:'long',year:'numeric'})}</h2><button class="textbtn" onclick="shiftMonth(1)">❯</button></div><div class="calendar">${['B.e','Ç.a','Ç','C.a','C','Ş','B'].map(t=>`<small>${t}</small>`).join('')}${'<span></span>'.repeat(o)}${Array.from({length:n},(_,i)=>{const k=key(new Date(y,m,i+1));return `<button class="${fasts[k]?'selected':''} ${k===key(new Date())?'today':''}" aria-pressed="${!!fasts[k]}" onclick="toggleFast('${k}')">${i+1}</button>`}).join('')}</div><div class="legend"><span>● Oruc tutulan gün</span><span style="color:#bd913f">◯ Bu gün</span></div></section><section class="card"><span class="bigicon">☾</span><h2>Niyyətiniz xeyirli olsun.</h2><p class="muted">Günə toxunaraq qeydinizi əlavə edin və ya silin. Qeydlər bu cihazda saxlanılır.</p><div class="metric"><b>${Object.values(fasts).filter(Boolean).length}</b><small>Qeyd edilmiş oruc günü</small></div><h3 style="margin-top:24px">Seçilmiş tarix</h3><p>İmsak: <strong>${prayers?.[0]||'—:—'}</strong> &nbsp; İftar: <strong>${prayers?.[3]||'—:—'}</strong></p>${note()}</section></div>`}
function shiftMonth(n){month.setDate(1);month.setMonth(month.getMonth()+n);render()}function toggleFast(k){if(k>key(new Date()))return toast('Gələcək gün üçün qeyd əlavə edilmir.');fasts[k]=!fasts[k];save('nur-fasts',fasts);render()}
function qibla(){return head('Qiblə','Üzünüzü müqəddəs Kəbəyə çevirin')+`<div class="split"><section class="card center"><div class="compass"><b class="north">N</b><b class="east">E</b><b class="south">S</b><b class="west">W</b><div class="needle" id="needle" style="transform:rotate(${bearing||0}deg)"><span>▣</span></div></div><h3>Qiblə istiqaməti</h3><h1>${bearing===null?'—':Math.round(bearing)+'°'}</h1><p class="muted">Coğrafi şimala nəzərən istiqamət</p></section><section class="card"><h2>İstiqamətinizi tapın</h2><p class="muted">Məkanınıza əsasən Kəbəyə doğru bucaq hesablanır. Sensor mövcud olduqda kompas cihazın istiqamətinə uyğun hərəkət edir.</p><button class="goldbtn" onclick="locate()">⌖ Məkanımı müəyyən et</button><p class="notice" id="compassStatus">Məkan icazəsi düyməyə toxunduqda soruşulur.</p><button class="textbtn" onclick="startCompass()">Kompas sensorunu aktiv et →</button></section></div>`}
function locate(){if(!navigator.geolocation)return toast('Məkan xidməti dəstəklənmir.');$('#compassStatus').textContent='Məkan müəyyən edilir…';navigator.geolocation.getCurrentPosition(p=>{const rad=v=>v*Math.PI/180,lat=rad(p.coords.latitude),d=rad(39.8262-p.coords.longitude);bearing=(Math.atan2(Math.sin(d),Math.cos(lat)*Math.tan(rad(21.4225))-Math.sin(lat)*Math.cos(d))*180/Math.PI+360)%360;render();$('#compassStatus').textContent='Məkan təyin olundu. Sensor aktiv deyilsə, ekranın üst tərəfini coğrafi şimala yönəldin.'},()=>{if($('#compassStatus'))$('#compassStatus').textContent='Məkan alınmadı. Brauzerin məkan icazəsini yoxlayın.'},{timeout:15000,enableHighAccuracy:true})}
async function startCompass(){try{if(typeof DeviceOrientationEvent==='undefined')return toast('Kompas sensoru mövcud deyil.');if(DeviceOrientationEvent.requestPermission&&await DeviceOrientationEvent.requestPermission()!=='granted')return toast('Sensor icazəsi verilmədi.');let received=false;window.addEventListener('deviceorientation',e=>{const h=e.webkitCompassHeading??(e.absolute&&e.alpha!=null?360-e.alpha:null);if(h===null)return;received=true;if($('#needle')&&bearing!==null)$('#needle').style.transform=`rotate(${bearing-h}deg)`;if($('#compassStatus'))$('#compassStatus').textContent='Kompas aktivdir. Cihazı üfüqi saxlayın.'});setTimeout(()=>{if(!received)toast('Sensor məlumatı alınmadı. Bucağı coğrafi şimala görə istifadə edin.')},4000)}catch{toast('Kompas aktivləşdirilmədi.')}}
function stats(){const list=Array.from({length:period},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(period-1-i));return {d,n:(records[key(d)]||[]).length}}),total=list.reduce((s,x)=>s+x.n,0);let streak=0,t=new Date();if(!(records[key(t)]||[]).length)t.setDate(t.getDate()-1);while((records[key(t)]||[]).length){streak++;t.setDate(t.getDate()-1)}const groups=period===7?list:Array.from({length:period===30?6:12},(_,i)=>{const a=list.slice(Math.floor(i*list.length/(period===30?6:12)),Math.floor((i+1)*list.length/(period===30?6:12)));return {d:a[0].d,n:a.reduce((s,x)=>s+x.n,0)/a.length}});return head('Statistika','Kiçik addımlar, davamlı ibadət')+`<section class="card"><div class="tabs">${[[7,'Həftə'],[30,'Ay'],[365,'İl']].map(([n,t])=>`<button class="${period===n?'active':''}" onclick="period=${n};render()">${t}</button>`).join('')}</div><h2>Namaz icrası</h2><div class="chart">${groups.map(x=>`<div class="barwrap"><span>${Math.round(x.n*10)/10}</span><div class="bar" style="height:${x.n*30}px"></div><span>${shortDateLabel(x.d,period===365)}</span></div>`).join('')}</div><div class="metrics"><div class="metric"><b>${streak} gün</b><small>Ardıcıl namaz qeydi</small></div><div class="metric"><b>${Math.round(total/(period*5)*100)}%</b><small>Ümumi icra · ${total} / ${period*5}</small></div></div><div class="quote"><p>“Hər yaxşı əməl, daha gözəl sabahlara aparan bir nurdur.”</p></div><p class="notice">Statistika bu brauzerdə saxlanan namaz qeydlərinizə əsaslanır.</p></section>`}
function setNotice(k,v){settings[k]=v;save('nur-settings',settings);toast(v?'Xatırlatma aktivdir. Tətbiq açıq qalmalıdır.':'Xatırlatma söndürüldü.')}
async function requestNotices(){if(!('Notification'in window))return toast('Brauzer bildirişləri dəstəklənmir.');toast(await Notification.requestPermission()==='granted'?'Bildiriş icazəsi verildi.':'Bildiriş icazəsi verilmədi.')}
function notifications(){return head('Bildirişlər','Xatırlatmaları özünüzə uyğunlaşdırın',true)+`<section class="card"><h2>Namaz bildirişləri</h2>${[...names.map((n,i)=>[String(i),n,icons[i]]),['fast','Oruc vaxtları','☾'],['dua','Gündəlik dua xatırlatması','♧']].map(([k,n,i])=>`<label class="row"><span class="symbol">${i}</span><strong class="grow">${n}</strong><input class="switch" type="checkbox" aria-label="${n}" ${settings[k]?'checked':''} onchange="setNotice('${k}',this.checked)"></label>`).join('')}<p class="notice">Xatırlatmalar yalnız tətbiq açıq və brauzer icazəsi verildiyi müddətdə işləyir. Bağlı tətbiq üçün fon bildirişləri dəstəklənmir.</p><button class="goldbtn" onclick="requestNotices()">Brauzer bildirişlərinə icazə ver</button></section>`}
function more(){return head('Daha çox','İbadət yolunuzda yanınızdayıq')+`<section class="card listgrid">${extra.map(([r,i,t])=>`<button class="row ${r==='themes'?'theme-menu-row':''}" onclick="go('${r}')"><span class="symbol">${i}</span><strong class="grow">${t}</strong>›</button>`).join('')}<button class="row more-restart" onclick="openOnboarding(true)"><span class="symbol">↻</span><span class="grow" data-localized="true"><strong>${ex('restart')}</strong><small>${ex('restartHint')}</small></span><span>›</span></button></section><div class="quote"><h2>Shams</h2><p>İslamla daha aydın sabahlara</p></div>`}
function render(){trackNavigation();route=location.hash.slice(1).split('/')[0]||'home';if(route==='home'&&key(day)!==key(placeToday())){day=placeToday();loadTimes();return}const active=route==='read'?'quran':route==='dua'?'duas':route;$('#desktopNav').innerHTML='<nav>'+[...nav.slice(0,3),...extra].map(([r,i,t])=>`<a class="navitem ${active===r?'active':''}" href="#${r}"><span>${i}</span>${t}</a>`).join('')+'</nav>';$('#bottomNav').innerHTML=nav.map(([r,i,t])=>`<a class="navitem ${active===r||(r==='more'&&!nav.some(n=>n[0]===active))?'active':''}" href="#${r}"><span>${i}</span>${t}</a>`).join('');const routeChanged=app.getAttribute?.('data-route')!==route;app.setAttribute?.('data-route',route);if(routeChanged){app.classList.remove('route-enter');window.requestAnimationFrame?.(()=>app.classList.add('route-enter'))}setupHeader();const id=location.hash.slice(1).split('/')[1];if(route==='read'){reader(Number(id)||1);return}app.innerHTML=({home:compactHome,tasbih:tasbihPage,learn:compactGuidePage,locations:locationsPage,language:languagePage,pro:proPage,mobile:localizedMobilePage,themes:themesPage,ramadan:ramadanPage,prayers:()=>prayerPage(),tracker:()=>prayerPage(true),quran:compactQuran,duas:duasSearchPage,dua:()=>duaDetail(Number(id)),fasting:compactFastingPage,qibla:compactQiblaPage,stats,notifications:compactNotificationsPage,more}[route]||home)();localizeUI()}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);app.scrollTop=0});render();loadTimes();loadSurahs();
const sent=read("nur-sent",{});setInterval(checkWorldReminders,30000);
initializeExperience();
initializeEnhancements();
initializeShams();
